def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The patterned region repeats horizontally. Find its period by choosing
    # the shortest period that explains the greatest number of visible cells.
    candidates = []
    for p in range(2, 13):
        total = matched = 0
        for r in range(3, h):
            counts = {}
            for c in range(3, w):
                v = grid[r][c]
                if v:
                    counts.setdefault(c % p, {})
                    counts[c % p][v] = counts[c % p].get(v, 0) + 1
            for group in counts.values():
                n = sum(group.values())
                total += n
                matched += max(group.values())
        candidates.append((matched / total if total else 0, -p, p))
    period = max(candidates)[2]

    for r in range(h):
        if r < 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1
            continue
        if r == 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 4
            continue

        # Restore the left frame where it was covered.
        for c, v in enumerate((1, 1, 4)):
            if out[r][c] == 0:
                out[r][c] = v

        # Infer each horizontal pattern value from the visible cells in that
        # row, indexed by absolute column modulo the repeated period.
        counts = {}
        for c in range(3, w):
            v = grid[r][c]
            if v:
                counts.setdefault(c % period, {})
                counts[c % period][v] = counts[c % period].get(v, 0) + 1

        for c in range(3, w):
            if out[r][c] == 0 and c % period in counts:
                out[r][c] = max(counts[c % period], key=counts[c % period].get)

    return out
